import {characterById} from './characters.js';
import {STARTER_EQUIPMENT,STARTER_MATERIALS,ECONOMY} from './equipment-catalog.js';
import {tutorialState,TUTORIAL_STAGES} from './tutorial.js';
export const SAVE_KEY='chemtopia.player',BACKUP_KEY=SAVE_KEY+'.backup',RECOVERY_KEY=SAVE_KEY+'.recovery',SAVE_VERSION=2;
export const SPAWN={x:600,y:570,facing:'front'};
const copy=v=>JSON.parse(JSON.stringify(v));
export function validateName(value){if(typeof value!=='string')return{ok:false,message:'Enter a player nickname.'};if(/[\u0000-\u001f\u007f-\u009f\u202a-\u202e\u2066-\u2069]/u.test(value))return{ok:false,message:'Use a visible player nickname without control characters.'};const name=value.normalize('NFKC').trim().replace(/\s+/gu,' ');if(!name||Array.from(name).length>24||!/^\p{L}[\p{L}\p{N} ._'’\-]*$/u.test(name))return{ok:false,message:'Use 1–24 characters, starting with a letter. Letters, numbers, spaces, apostrophes and hyphens are welcome.'};return{ok:true,name};}
export function newPlayer(name,characterId){const n=validateName(name);if(!n.ok)throw Error(n.message);if(!characterById(characterId))throw Error('Choose one of the six existing characters.');return{schemaVersion:SAVE_VERSION,profileId:globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),name:n.name,characterId,currency:ECONOMY.startingBalance,equipment:{...STARTER_EQUIPMENT},materials:{...STARTER_MATERIALS},completed:[],tutorial:tutorialState(),position:{...SPAWN},claims:[],attempts:{},revision:0,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};}
function counts(value){if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Invalid inventory.');const entries=Object.entries(value);if(entries.length>500)throw Error('Inventory is too large.');for(const [id,n]of entries)if(!/^[a-z][a-z0-9-]{0,63}$/.test(id)||['constructor','prototype'].includes(id)||!Number.isSafeInteger(n)||n<0||n>99999)throw Error('Invalid inventory quantity.');return Object.fromEntries(entries);}
export function validatePlayer(value){if(!value||value.schemaVersion!==SAVE_VERSION)throw Error('Unsupported save version.');const n=validateName(value.name);if(!n.ok||!characterById(value.characterId))throw Error('Invalid player identity.');if(!Number.isSafeInteger(value.currency)||value.currency<0||value.currency>1e9)throw Error('Invalid credit balance.');const s=copy(value);s.name=n.name;s.profileId=typeof s.profileId==='string'&&s.profileId.length<150?s.profileId:'v2-'+(s.createdAt||'legacy')+'-'+s.characterId;s.equipment=counts(s.equipment);s.materials=counts(s.materials);if(!Array.isArray(s.completed)||!Array.isArray(s.claims)||s.claims.length>10000||![...s.completed,...s.claims].every(x=>typeof x==='string'&&x.length<=150))throw Error('Invalid progress record.');s.completed=[...new Set(s.completed)];s.claims=[...new Set(s.claims)];if(!s.tutorial||!Number.isInteger(s.tutorial.stage)||s.tutorial.stage<0||s.tutorial.stage>TUTORIAL_STAGES.length||!Array.isArray(s.tutorial.flags)||!s.tutorial.flags.every(x=>typeof x==='string'))throw Error('Invalid tutorial record.');s.tutorial.flags=[...new Set(s.tutorial.flags)];if(!s.position||![s.position.x,s.position.y].every(Number.isFinite))s.position={...SPAWN};s.position.x=Math.max(25,Math.min(1175,s.position.x));s.position.y=Math.max(300,Math.min(720,s.position.y));s.position.facing=s.position.facing==='back'?'back':'front';s.revision=Number.isSafeInteger(s.revision)&&s.revision>=0?s.revision:0;s.attempts=s.attempts&&typeof s.attempts==='object'&&!Array.isArray(s.attempts)?s.attempts:{};for(const [id,a]of Object.entries(s.attempts)){if(!/^[a-z][a-z0-9-]*$/.test(id)||!a||typeof a.id!=='string'||!a.id||a.id.length>150||a.experiment!==id||!['active','completed','abandoned'].includes(a.status))throw Error('Invalid saved experiment attempt.');a.supplies=counts(a.supplies);}return s;}
export function migrateSave(raw){const data=typeof raw==='string'?JSON.parse(raw):copy(raw);if(data.schemaVersion===SAVE_VERSION)return validatePlayer(data);if(data.version===1||data.schemaVersion===1){const p=newPlayer(data.playerName||data.name,data.characterId);p.profileId=data.profileId||'v1-'+data.characterId+'-'+(data.playerName||data.name);p.createdAt=data.createdAt||'legacy-v1';p.currency=data.credits??data.currency??p.currency;p.equipment=Array.isArray(data.equipment)?Object.fromEntries(data.equipment.map(id=>[id,1])):(data.equipment||p.equipment);p.materials=data.consumables||data.materials||p.materials;p.completed=data.completedExperiments||data.completed||[];p.position=data.position||p.position;p.tutorial={...tutorialState(),stage:data.tutorialStep||0,flags:data.tutorial?.flags||[]};return validatePlayer(p);}throw Error('This save has an unrecognised or newer version; it has not been overwritten.');}
export function createPlayerStore(storage){let available=true;if(storage===undefined){try{storage=globalThis.localStorage;}catch{available=false;}}if(!storage)available=false;let memory=null,issue='',queue=Promise.resolve();
 function readRaw(){if(!available)return memory?JSON.stringify(memory):null;try{return storage.getItem(SAVE_KEY);}catch(e){available=false;issue='Browser storage is unavailable. Progress is temporary in this tab.';return memory?JSON.stringify(memory):null;}}
 function load(){const raw=readRaw();if(!raw)return{status:'empty',player:null,persistent:available,warning:issue||(!available?'Browser storage is unavailable. Progress is temporary in this tab.':'')};try{const player=migrateSave(raw);memory=player;return{status:'ready',player:copy(player),persistent:available,warning:issue};}catch(e){let backup=null;try{backup=available?storage.getItem(BACKUP_KEY):null;}catch{}return{status:'protected',player:null,persistent:available,error:e.message,raw,backup};}}
 function write(player,{previous,archive=false}={}){const clean=validatePlayer(player);clean.updatedAt=new Date().toISOString();clean.revision=(clean.revision||0)+1;if(available){try{const old=storage.getItem(SAVE_KEY);if(previous!==undefined&&old!==previous)throw Error('Progress changed in another tab. Retry this action.');if(old)storage.setItem(archive?RECOVERY_KEY:BACKUP_KEY,old);storage.setItem(SAVE_KEY,JSON.stringify(clean));}catch(e){if(/another tab/.test(e.message))throw e;throw Error('Could not save progress. Existing data was kept. Free browser storage and retry.');}}memory=clean;return copy(clean);}
 function start(name,characterId,{confirmed=false}={}){const old=readRaw();if(old&&!confirmed)throw Error('Confirm New Game before replacing existing progress.');return write(newPlayer(name,characterId),{previous:old,archive:Boolean(old)});}
 function update(reducer){const loaded=load();if(loaded.status!=='ready')throw Error(loaded.error||'Start an adventure first.');const before=readRaw(),next=copy(loaded.player),result=reducer(next);return{player:write(next,{previous:before}),result};}
 function transact(reducer){const run=()=>globalThis.navigator?.locks?.request?globalThis.navigator.locks.request('chemtopia-player-save',()=>update(reducer)):update(reducer);const job=queue.then(run);queue=job.catch(()=>{});return job;}
 function restoreBackup(){if(!available)throw Error('Browser storage is unavailable.');const raw=storage.getItem(BACKUP_KEY);if(!raw)throw Error('No backup is available.');return write(migrateSave(raw),{previous:readRaw(),archive:true});}
 return{load,start,update,transact,restoreBackup,get warning(){return issue||(!available?'Progress is temporary: browser storage is unavailable.':'');}};
}
export const playerStore=createPlayerStore();
